class TextEditor { private val left=StringBuilder();private val right=StringBuilder();fun addText(text:String){left.append(text)}fun deleteText(k:Int):Int{val removed=minOf(k,left.length);left.setLength(left.length-removed);return removed}private fun view()=left.substring(maxOf(0,left.length-10));fun cursorLeft(kValue:Int):String{var k=kValue;while(k>0&&left.isNotEmpty()){right.append(left[left.length-1]);left.setLength(left.length-1);k--};return view()}fun cursorRight(kValue:Int):String{var k=kValue;while(k>0&&right.isNotEmpty()){left.append(right[right.length-1]);right.setLength(right.length-1);k--};return view()} }
